import java.util.*;
import java.io.*;

public class Main {
    static final int MAX_DIGITS = 7;
    static final int BASE = 1000000;
    static final long MOD1 = 998244353L;
    static final long MOD2 = 1000000007L;
    static long total, counter;
    static List<Integer>[] digit_vals = new ArrayList[MAX_DIGITS];
    static int result;
    static int[] prefix_sum = new int[MAX_DIGITS];

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        total = Long.parseLong(br.readLine().trim());
        for (int i = 0; i < MAX_DIGITS; i++) {
            digit_vals[i] = new ArrayList<>();
        }

        // Build digit values recursively
        build_vals(0, 0);

        // Sort and compute prefix sums
        for (int d = 0; d <= 6; d++) {
            Collections.sort(digit_vals[d]);
            long sum = 0;
            for (int v : digit_vals[d]) {
                sum = (sum + v) % MOD2;
            }
            prefix_sum[d] = (int) sum;
        }

        counter = 0;
        result = 0;

        // Traverse recursively
        traverse(0, 0L);

        System.out.println(result);
    }

    static void build_vals(int level, int val) {
        counter++;
        digit_vals[level].add((int)((counter - val + MOD1) % MOD1));
        if (level == 6) return;
        for (int digit = 0; digit < 10; digit++) {
            build_vals(level + 1, val * 10 + digit);
        }
    }

    static void traverse(int depth, long v) {
        if (v > total) return;
        if (depth != 0) {
            if (v * BASE > total / 10 && (v + 1) * BASE - 1 <= total) {
                for (int i = 0, power = 1; i <= 6; i++, power *= 10) {
                    long coef = (counter - (v * power) % MOD1 + MOD1) % MOD1;
                    int idx = lowerBound(digit_vals[i], (int)(MOD1 - coef));
                    long sum = 0;
                    for (int val : digit_vals[i]) {
                        sum = (sum + val) % MOD2;
                    }
                    long prefixSum = prefix_sum[i];
                    long size = digit_vals[i].size();
                    long countLess = idx;
                    long totalSum = (coef * size) % MOD2;
                    long sumLess = 0;
                    for (int j = 0; j < idx; j++) {
                        sumLess = (sumLess + digit_vals[i].get(j)) % MOD2;
                    }
                    result = (int)((result + totalSum + prefixSum - (MOD1 * countLess) % MOD2 + MOD2) % MOD2);
                }
                for (int i = 0; i <= 6; i++) {
                    counter += digit_vals[i].size();
                }
                return;
            }
            result = (int)((result + (++counter - v % MOD1 + MOD1) % MOD1) % MOD2);
        }
        for (int c = (depth == 0 ? 1 : 0); c < 10; c++) {
            traverse(depth + 1, v * 10 + c);
        }
    }

    static int lowerBound(List<Integer> list, int key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }
}
